    expect(autocompleteValue).toBe('email');
  });

  test('should have correct autocomplete attribute for phone field', async ({ page }) => {
    const phoneInput = page.getByPlaceholder('Phone');
    const autocompleteValue = await phoneInput.getAttribute('autocomplete');
    expect(autocompleteValue).toBe('tel');
  });

  test('should have correct autocomplete attribute for address field', async ({ page }) => {
    const addressInput = page.getByPlaceholder('Address');
    const autocompleteValue = await addressInput.getAttribute('autocomplete');
    expect(autocompleteValue).toBe('street-address');
  });

  test('should have correct autocomplete attribute for city field', async ({ page }) => {
    const cityInput = page.getByPlaceholder('City');
    const autocompleteValue = await cityInput.getAttribute('autocomplete');
    expect(autocompleteValue).toBe('address-level2');
  });

  test('should have correct autocomplete attribute for postal-code field', async ({ page }) => {
    const zipcodeInput = page.getByPlaceholder('Zip Code');
    const autocompleteValue = await zipcodeInput.getAttribute('autocomplete');
    expect(autocompleteValue).toBe('postal-code');
  });

  test('should have correct autocomplete attribute for password field', async ({ page }) => {
