  });

  test('should have autocomplete attributes on all form inputs', async ({ page }) => {
    const inputs = page.locator('input[type="text"], input[type="email"], input[type="tel"], input[type="password"]');
    const count = await inputs.count();

    for (let i = 0; i < count; i++) {
      const input = inputs.nth(i);
      const autocompleteAttr = await input.getAttribute('autocomplete');
      expect(autocompleteAttr).not.toBeNull();
      expect(autocompleteAttr).toBeTruthy();
    }
  });

  test('should allow browser autocomplete functionality with correct attributes', async ({ page }) => {
    const firstNameInput = page.getByPlaceholder('First Name');
    const lastNameInput = page.getByPlaceholder('Last Name');
